import dataset from './data.js';
import runtime from './runtime.js';
import {makePacket,clone} from './engine.js';
import {retrieveEvidence} from './retrieval.js';

const $=s=>document.querySelector(s);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=0)=>typeof v==='number'&&Number.isFinite(v)?new Intl.NumberFormat('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v):'—';
const money=(v,d=0)=>typeof v==='number'&&Number.isFinite(v)?'₹'+n(v,d):'—';
const percent=(v,d=1)=>typeof v==='number'&&Number.isFinite(v)?n(v*100,d)+'%':'—';
const dated=value=>new Date(value+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const paths={search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16 m-6-6 6 6-6 6',up:'m6 15 6-6 6 6',down:'m6 9 6 6 6-6',external:'M14 3h7v7 m0-7-11 11 M10 3H4v17h17v-6',close:'m6 6 12 12 M6 18 18 6',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 12h8 M8 16h6',download:'M12 3v12 m-5-5 5 5 5-5 M5 16v5h14v-5',check:'m5 12 4 4L19 6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',save:'M6 3h12v18l-6-4-6 4z',sliders:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',send:'M12 20V4 m-6 6 6-6 6 6',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',code:'m8 6-6 6 6 6 m8-12 6 6-6 6 m-3-15-2 18',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7z m-4 9 3 3 5-6',upload:'M12 17V3 m-5 5 5-5 5 5 M4 16v5h16v-5'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]??paths.file}"/></svg>`;
function read(key,fallback){try{const x=JSON.parse(localStorage.getItem('artha.'+key));return x??fallback;}catch{return fallback;}}
function write(key,value){try{localStorage.setItem('artha.'+key,JSON.stringify(value));}catch{toast('Local storage is unavailable. Export a copy of your work.');}}
const company=dataset.companies[0],peers=clone(dataset.peers),compiled=dataset.precomputed;
const cases=compiled.cases[company.id];
const state={view:['company','valuation','research'].includes(location.hash.slice(1))?location.hash.slice(1):'company',scenario:'base',a:clone(cases.base.assumptions),r:clone(cases.base),chart:'revenue',subview:'model',fullForecast:false,statement:'income',statementsOpen:false,messages:[],asking:false,busy:false,error:null,assistantMode:'evidence',market:read('market',{}),scenarios:read('scenarios',[]),audit:read('audit',[])};
let toastTimer,requestId=0,modalReturn=null;
const button=(label,action,style='',ico='')=>`<button class="btn ${style}" data-action="${action}">${ico?icon(ico):''}${e(label)}</button>`;
const linkButton=(label,action,ico='arrow')=>button(label,action,'btn-quiet',ico);
function event(action,detail){state.audit.unshift({action,detail,time:new Date().toISOString()});state.audit=state.audit.slice(0,100);write('audit',state.audit);}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
async function api(route,body){const response=await fetch(route,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const value=await response.json();if(!response.ok&&!Array.isArray(value.errors))throw new Error(value.error??'The research service is unavailable.');return value;}
async function refresh(persist=false){if(!runtime.api)return;const id=++requestId;state.busy=true;state.error=null;render();try{const r=await api('/api/valuation',{companyId:company.id,assumptions:state.a,persist,marketOverrides:state.market});if(id!==requestId)return;state.r=r;}catch(error){if(id!==requestId)return;state.error=error.message;}finally{if(id===requestId){state.busy=false;render();}}}
function go(view){state.view=view;location.hash=view;closeDialog();render();window.scrollTo({top:0,behavior:'instant'});}
function chooseCase(name){state.scenario=name;state.a=clone(cases[name].assumptions);event('Scenario selected',name+' case');if(runtime.api)refresh();else{state.r=clone(cases[name]);render();}}
function scenarioControl(){return `<div class="segmented" role="group" aria-label="Valuation scenario">${['base','bull','bear'].map(s=>`<button class="segment ${state.scenario===s?'active':''}" data-case="${s}">${s[0].toUpperCase()+s.slice(1)} case</button>`).join('')}</div>`;}
function meta(){return `<div class="meta-line"><span>${e(company.ticker)} · BSE ${e(company.scrip)}</span><span class="divider"></span><span>FY24–FY26 consolidated</span><span class="divider"></span><button data-action="method">Retrospective study ${icon('info')}</button>${state.busy?'<span class="loading-text"><span class="loading-dot"></span>Updating</span>':''}</div>`;}
function sectionHead(title,description,control=''){return `<div class="section-heading"><div><h2>${title}</h2><p>${description}</p></div>${control}</div>`;}
function financialRows(type){const h=company.historical,analytics=state.r.analytics?.annuals??cases.base.analytics.annuals;const groups={income:[['Revenue',x=>x.revenue],['Operating profit, pre-exception',x=>x.ebit],['Profit attributable to owners',x=>x.netIncome],['Diluted EPS · INR',(_,i)=>analytics[i]?.diluted_eps]],balance:[['Total assets',x=>x.assets],['Total equity',x=>x.equity],['Total liabilities',x=>x.liabilities],['Cash and cash equivalents',x=>x.cash],['Trade receivables',x=>x.receivables],['Trade payables',x=>x.payables]],cash:[['Cash flow from operations',x=>x.cfo],['Cash flow from investing',x=>x.cfi],['Cash flow from financing',x=>x.cff],['Capital expenditure',x=>x.capex],['Closing cash',x=>x.closingCash]]};return `<div class="table-wrap"><table class="data-table"><thead><tr><th>INR crore unless stated</th>${h.map(x=>`<th>FY${x.year}</th>`).join('')}</tr></thead><tbody>${groups[type].map(([label,fn])=>`<tr><td>${label}</td>${h.map((x,i)=>`<td>${n(fn(x,i),label.includes('EPS')?2:0)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function historyChart(){const key=state.chart,h=company.historical,max=Math.max(...h.map(x=>x[key]))*1.22,w=1010,height=245,left=54,right=31,top=26,bottom=38,x=i=>left+i*(w-left-right)/2,y=v=>top+(max-v)*(height-top-bottom)/max;const pts=h.map((p,i)=>`${i?'L':'M'}${x(i)} ${y(p[key])}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 ${w} ${height}" role="img" aria-label="Reported ${key==='revenue'?'revenue':key==='ebit'?'operating profit':'operating cash flow'} for FY2024 through FY2026, in INR crore">${[0,.33,.66,1].map(t=>`<line x1="${left}" y1="${y(max*t)}" x2="${w-right}" y2="${y(max*t)}" stroke="#eeeeF2" stroke-dasharray="2 5"/><text x="${left-13}" y="${y(max*t)+4}" text-anchor="end" class="chart-label">${n(max*t/1000)}k</text>`).join('')}<path d="${pts}" fill="none" stroke="#658bb6" stroke-width="2.3" stroke-linecap="round"/>${h.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p[key])}" r="4" fill="#658bb6" stroke="white" stroke-width="3"><title>FY${p.year}: ${money(p[key])} crore</title></circle><text x="${x(i)}" y="${height-11}" text-anchor="middle" class="chart-label">FY${p.year}</text>${i===2?`<text x="${x(i)-3}" y="${y(p[key])-16}" text-anchor="end" fill="#777f8d" style="font:12px var(--font)">${money(p[key])}</text>`:''}`).join('')}</svg>`;}
function companyView(){const r=state.r,h=company.historical.at(-1),a=r.analytics?.annuals.at(-1)??cases.base.analytics.annuals.at(-1),chartLabels={revenue:'Revenue',ebit:'Operating profit',cfo:'Operating cash flow'};return `<div class="hero"><div><p class="eyebrow">A closer look.</p><h1>Infosys, in perspective.</h1><p class="hero-subtitle">Explore the financials.<br>Shape your own valuation.</p>${meta()}</div><div class="hero-value"><span class="label">Your ${state.scenario==='custom'?'custom':state.scenario+'-case'} value</span><strong>${money(r.perShare,2)}</strong><span class="sub">per share · provisional</span></div></div>
<div class="metrics"><div class="metric"><p class="metric-label">FY26 reported revenue</p><div class="metric-value">${money(h.revenue)}<span class="metric-unit">crore</span></div><p class="metric-note"><span class="positive">${percent(a.revenue_growth)}</span> year-on-year growth</p></div><div class="metric"><p class="metric-label">Operating margin</p><div class="metric-value">${percent(a.operating_margin)}</div><p class="metric-note">Before exceptional items</p></div><div class="metric"><p class="metric-label">Operating cash flow</p><div class="metric-value">${money(h.cfo)}<span class="metric-unit">crore</span></div><p class="metric-note">Reported consolidated cash flow</p></div></div>
${sectionHead('Performance, over time.','Three financial years. A consistent basis.',`<div class="segmented" role="group" aria-label="Historical chart metric">${[['revenue','Revenue'],['ebit','Profit'],['cfo','Cash flow']].map(([k,label])=>`<button class="segment ${state.chart===k?'active':''}" data-chart="${k}">${label}</button>`).join('')}</div>`)}
<div class="paper performance"><div class="chart-meta"><div class="chart-current">${money(h[state.chart])}<span>FY2026 ${chartLabels[state.chart].toLowerCase()} · INR crore</span></div><div class="chart-legend"><span><i></i>Reported financials</span></div></div>${historyChart()}<div class="chart-caption"><span>Source: official Infosys consolidated statements. ${state.chart==='ebit'?'Operating profit excludes exceptional items.':''}</span><button class="text-link" data-action="evidence">View the evidence →</button></div></div>
<div class="quiet-card"><div><h3>The value depends on your assumptions.</h3><p>Explore base, bull and bear cases. Change the inputs and follow each cash flow through to its present value.</p></div>${linkButton('Explore valuation','valuation')}</div>
<details class="disclosure" data-remember="statementsOpen" ${state.statementsOpen?'open':''}><summary>Financial statements. The key lines.</summary><div class="details-body"><div class="segmented" role="group" aria-label="Financial statement">${[['income','Income statement'],['balance','Balance sheet'],['cash','Cash flow']].map(([id,label])=>`<button class="segment ${state.statement===id?'active':''}" data-statement="${id}">${label}</button>`).join('')}</div><div class="spaced">${financialRows(state.statement)}</div><p class="footnote">Selected reported lines, not a full notes-of-accounts extraction. Full statements and source definitions are available in Evidence.</p></div></details>
<details class="disclosure"><summary>How healthy are the fundamentals?</summary><div class="details-body"><div class="table-wrap"><table class="data-table"><thead><tr><th>Metric</th>${(r.analytics?.annuals??cases.base.analytics.annuals).map(x=>`<th>FY${x.fiscal_year}</th>`).join('')}</tr></thead><tbody>${[['Return on equity','roe','pct'],['Return on assets','roa','pct'],['Current ratio','current_ratio','multiple'],['Debt / equity','debt_to_equity','multiple'],['Asset turnover','asset_turnover','multiple'],['EPS growth','eps_growth','pct']].map(([label,key,type])=>`<tr><td>${label}</td>${(r.analytics?.annuals??cases.base.analytics.annuals).map(x=>`<td>${x[key]===null?'—':type==='pct'?percent(x[key]):n(x[key],2)+'×'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="footnote">ROE and ROA use average balance-sheet denominators. Missing prior-period evidence remains unavailable. ${linkButton('Read the methodology','method','info')}</p></div></details>`;}
function forecastTable(full=state.fullForecast,print=false){const f=state.r.forecast??[];const rows=full?[['Revenue','revenue'],['Operating profit','ebit'],['NOPAT','nopat'],['+ Depreciation','da'],['− Capital expenditure','capex'],['− Increase in working capital','deltaNwc'],['Free cash flow','fcff'],['Present value','pv']]:[['Revenue','revenue'],['Operating profit','ebit'],['Free cash flow','fcff'],['Present value','pv']];return `<div class="table-wrap"><table class="data-table"><thead><tr><th>INR crore</th>${f.map(r=>`<th>FY${r.year}E</th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr class="${key==='fcff'?'emphasis':''}"><td>${label}</td>${f.map(r=>`<td>${n(r[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function heatmap(){const s=state.r.sensitivity;if(!s)return '';const values=s.values.flat().filter(v=>v!==null),lo=Math.min(...values),hi=Math.max(...values);return `<div class="heatmap"><table class="heatmap-table" aria-label="Per-share valuation sensitivity"><thead><tr><th>WACC ↓<br>Growth →</th>${s.growth.map(g=>`<th>${percent(g)}</th>`).join('')}</tr></thead><tbody>${s.wacc.map((w,i)=>`<tr><th>${percent(w)}</th>${s.values[i].map((v,j)=>`<td class="${i===2&&j===2?'base':''}" style="background:${v===null?'#f5f5f7':`rgba(152,183,220,${.1+(v-lo)/(hi-lo||1)*.38})`}">${money(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="footnote">The outlined cell is your active scenario. Each cell rebuilds terminal-year reinvestment. Invalid combinations remain unavailable.</p></div>`;}
function extraMultiples(){const rows=state.r.peerComparison??cases.base.peerComparison,implied=state.r.peerImpliedValues??cases.base.peerImpliedValues??{};return `<details class="disclosure"><summary>Explore other multiples and implied values.</summary><div class="details-body"><table class="data-table"><thead><tr><th>Company</th><th>P / book</th><th>P / sales</th><th>EV / EBITDA</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${e(p.id===company.id?'Infosys':p.name)}</td><td>${p.pb===null?'—':n(p.pb,1)+'×'}</td><td>${p.ps===null?'—':n(p.ps,1)+'×'}</td><td>${p.evEbitda===null?'—':n(p.evEbitda,1)+'×'}</td></tr>`).join('')}</tbody></table><p class="footnote">Additional multiples need reviewed book equity or EBITDA. A median is calculated only from positive, supported comparable multiples.</p><table class="data-table"><thead><tr><th>Method</th><th>Peers available</th><th>Median</th><th>Implied value / share</th></tr></thead><tbody>${[['pe','P/E'],['pb','P/book'],['ps','P/sales'],['ev_ebitda','EV/EBITDA'],['ev_ebit','EV/EBIT'],['ev_revenue','EV/revenue']].map(([k,label])=>{const x=implied[k]??{};return `<tr><td>${label}</td><td>${x.peer_count??0}</td><td>${x.median_multiple==null?'—':n(x.median_multiple,1)+'×'}</td><td>${money(x.implied_value_per_share,2)}</td></tr>`;}).join('')}</tbody></table></div></details>`;}
function peersPanel(){const rows=state.r.peerComparison??cases.base.peerComparison;return `${sectionHead('A useful point of comparison.','FY26 financials, matched on a reported basis.',button('Add market evidence','market','btn-outline btn-small','upload'))}<div class="paper peer-table"><table class="data-table"><thead><tr><th>Company</th><th>Revenue · Cr</th><th>EBIT margin</th><th>Net margin</th><th>P/E</th><th>EV / EBIT</th><th>EV / revenue</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${e(p.id===company.id?'Infosys':p.name)}</td><td>${n(p.revenue)}</td><td>${percent(p.ebitMargin)}</td><td>${percent(p.netMargin)}</td><td>${p.pe===null?'—':n(p.pe,1)+'×'}</td><td>${p.evEbit===null?'—':n(p.evEbit,1)+'×'}</td><td>${p.evRevenue===null?'—':n(p.evRevenue,1)+'×'}</td></tr>`).join('')}</tbody></table><p class="peer-foot">Reported EBIT and owner profit are used consistently. Missing compatible prices or bridge inputs leave multiples unavailable. Infosys pre-exception profit appears separately in the Company view.</p></div><div class="peer-bars"><div>${rows.map(p=>`<div class="bar-row ${p.id===company.id?'subject':''}"><span>${e(p.id===company.id?'Infosys':p.name)}</span><div class="bar-track"><span style="width:${Math.min(100,p.ebitMargin/.3*100)}%"></span></div><strong>${percent(p.ebitMargin)}</strong></div>`).join('')}</div><div class="peer-explainer"><h3>Context makes a multiple useful.</h3><p>Growth, business mix and capital intensity can explain different valuations. A matching currency and reporting period are the starting point.</p>${linkButton('Explore sources and definitions','evidence')}</div></div>${extraMultiples()}`;}
function valuationView(){const r=state.r;return `<div class="hero valuation-hero"><div><p class="eyebrow">Valuation</p><h1>Make the assumptions<br>your own.</h1><p class="hero-subtitle">Understand what moves the value.</p>${meta()}</div>${button('Saved scenarios','saved','btn-outline','save')}</div><div class="valuation-tools">${scenarioControl()}<div class="row"><span class="range-label">${state.scenario==='custom'?'Custom assumptions':'Educational assumptions'}</span>${button('Save scenario','save','btn-outline btn-small','save')}</div></div><div class="model-result"><div class="result-stat main"><label>Scenario value per share</label><strong>${money(r.perShare,2)}</strong><p><span class="status-dot"></span>Provisional · net outstanding shares</p></div><div class="result-stat"><label>Equity value · INR crore</label><strong>${money(r.equityValue)}</strong><p>After cash, debt, leases and NCI</p></div><div class="result-stat"><label>Terminal contribution</label><strong>${percent(r.terminalContribution)}</strong><p>Share of operating enterprise value</p></div></div><div class="assumptions-strip"><div class="inputs-summary"><span>WACC<strong>${percent(state.a.wacc)}</strong></span><span>Operating margin<strong>${percent(state.a.margin)}</strong></span><span>Terminal growth<strong>${percent(state.a.terminalGrowth)}</strong></span></div>${linkButton('Edit assumptions','assumptions','sliders')}</div><div class="subnav" role="group" aria-label="Valuation section"><button data-subview="model" class="${state.subview==='model'?'active':''}">Cash-flow model</button><button data-subview="peers" class="${state.subview==='peers'?'active':''}">Peer comparison</button></div>${state.subview==='peers'?peersPanel():`<div class="paper forecast-panel"><div class="panel-head"><div><h3>Five years, laid out.</h3><p>From revenue to discounted free cash flow.</p></div>${button('Export CSV','csv','btn-outline btn-small','download')}</div>${forecastTable()}<div class="table-toggle">${linkButton(state.fullForecast?'Show the essentials':'See the full cash-flow detail','forecast-detail',state.fullForecast?'up':'down')}</div></div><details class="disclosure"><summary>Explore valuation sensitivity.</summary><div class="details-body">${heatmap()}</div></details><details class="disclosure"><summary>Follow the enterprise-to-equity bridge.</summary><div class="details-body paper"><table class="data-table"><tbody>${[['Operating enterprise value',r.enterpriseValue],['+ Assumed excess cash',state.a.excessCash],['− Debt',state.a.debt],['− Lease liabilities',state.a.leases],['− Non-controlling interests',state.a.nci],['Equity value',r.equityValue]].map(([label,value],i)=>`<tr class="${i===5?'emphasis':''}"><td>${label}</td><td>${money(value)} crore</td></tr>`).join('')}</tbody></table></div></details>`}<button class="review-link" data-action="review"><span><strong>Keep the limitations in view.</strong>${r.warnings?.length??0} review items travel with this valuation.</span>${icon('arrow')}</button>`;}
function citation(s,index){return `<a class="answer-source" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${index+1}. ${e(s.id.includes('fy26')?'FY26 source':s.id.includes('fy25')?'FY25 source':s.title.split(' — ')[0])}${icon('external')}</a>`;}
function researchView(){return `<div class="hero research-hero"><div><p class="eyebrow">Research</p><h1>Ask the numbers.</h1><p class="hero-subtitle">Follow an explanation back to its evidence.</p>${meta()}</div>${state.messages.length?button('New conversation','new-chat','btn-outline'):''}</div><div class="research-layout"><div><div class="conversation" id="conversation" aria-live="polite">${state.messages.length?state.messages.map(m=>m.role==='user'?`<div class="message-question">${e(m.text)}</div>`:`<article class="message-answer"><span class="answer-label">${m.answer.mode==='llm'?'AI explanation · citations checked':'Evidence-based explanation'}</span><h3>${e(m.answer.title)}</h3><p>${e(m.answer.body)}</p><div class="answer-sources">${m.answer.citations.map(citation).join('')}</div>${m.answer.retrieval?.length?`<details class="retrieval-details"><summary>${m.answer.retrieval.length} matching source facts</summary>${m.answer.retrieval.map(d=>`<div class="retrieval-item"><strong>FY${d.year} · ${e(d.field.replaceAll('_',' '))}</strong>${e(d.text.slice(0,230))}<br><a href="${e(d.sourceUrl)}" target="_blank" rel="noopener noreferrer">PDF ${e(d.pdfPage)}</a></div>`).join('')}</details>`:''}</article>`).join(''):`<div class="research-welcome"><p class="welcome-line">Start with what matters to you.</p><p>Ask about the company’s performance, the assumptions behind its valuation, or the evidence supporting a result.</p><div class="suggestions">${['What does the revenue history show?','How does WACC change the valuation?','What are the model limitations?'].map(q=>`<button class="suggestion" data-question="${e(q)}">${e(q)}</button>`).join('')}</div></div>`}${state.asking?'<p class="loading-text"><span class="loading-dot"></span>Reading the evidence.</p>':''}</div><form class="question-form" id="question-form"><label for="question" class="sr-only">Ask a research question</label><textarea id="question" rows="1" maxlength="2000" placeholder="Ask about revenue, valuation or sources…" ${state.asking?'disabled':''}></textarea><button class="send-button" type="submit" aria-label="Send question" ${state.asking||state.busy?'disabled':''}>${icon('send')}</button></form><p class="research-caption">${state.assistantMode==='optional_llm'?'The configured AI explains verified results.':'Evidence mode uses the loaded snapshot; no LLM is connected.'} Financial assumptions stay explicit.</p></div><aside><div class="context-block"><h3>Your research context</h3><div class="context-row"><span>Company</span><strong>${e(company.ticker)}</strong></div><div class="context-row"><span>Periods</span><strong>FY24–FY26</strong></div><div class="context-row"><span>Scenario</span><strong>${e(state.scenario)}</strong></div><div class="context-row"><span>Value / share</span><strong>${money(state.r.perShare,2)}</strong></div><div class="context-row"><span>Evidence</span><strong>${company.sources.length} documents</strong></div></div><div class="context-block"><h3>A useful boundary.</h3><p>This research view explains approved facts and model outputs. Unsupported questions receive a coverage limitation.</p>${linkButton('Explore the evidence','evidence','file')}</div></aside></div>`;}
function printReport(){const r=state.r;if(!r.valid)return '';return `<article class="print-report"><p class="print-meta">ARTHA / EQUITY RESEARCH</p><h1>${e(company.name)}</h1><p class="print-meta">Retrospective FY26 study · Consolidated · INR crore<br>Effective ${state.a.valuationDate} · Information cutoff ${state.a.informationCutoff} · ${e(state.scenario)} scenario</p><div class="print-values"><div>Scenario value / share<strong>${money(r.perShare,2)}</strong></div><div>Enterprise value · Cr<strong>${money(r.enterpriseValue)}</strong></div><div>Equity value · Cr<strong>${money(r.equityValue)}</strong></div></div><h2>Assumptions</h2><p>WACC ${percent(state.a.wacc)} · terminal growth ${percent(state.a.terminalGrowth)} · operating margin ${percent(state.a.margin)} · operating tax ${percent(state.a.tax)}. Revenue growth: ${state.a.growth.map(g=>percent(g)).join(', ')}. Share denominator: ${n(r.shares,7)} crore net shares.</p><h2>Forecast</h2>${forecastTable(true,true)}<h2>Review items</h2><ul>${r.warnings.map(w=>`<li>${e(w)}</li>`).join('')}</ul><h2>Sources</h2>${company.sources.map(s=>`<p>${e(s.title)} · ${e(s.pages)} · Published ${s.publicationDate}<br><a href="${e(s.url)}">${e(s.url)}</a></p>`).join('')}<p class="print-meta">Model ${r.modelVersion} · Deterministic Python calculations. Educational research; no investment recommendation.</p></article>`;}
function render(){const r=state.r,valid=r?.valid;$('#app').innerHTML=`<div class="app-shell"><header class="topbar"><div class="nav-wrap"><a class="wordmark" href="#company" aria-label="Artha home">artha.</a><nav class="nav-links" aria-label="Main navigation">${[['company','Company'],['valuation','Valuation'],['research','Research']].map(([view,label])=>`<a href="#${view}" class="nav-link ${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="nav-actions"><button class="nav-tool" data-action="search" aria-label="Find a company">${icon('search')}INFY</button><span class="nav-divider"></span><button class="nav-tool" data-action="evidence">Evidence</button>${button('Export report','export','','download')}</div></div></header>${!runtime.api?'<div class="preview-note">Interactive desktop preview. Custom calculations and persistent history run in the complete application. <a href="/downloads/artha-equity-project.zip" download>Get the project</a></div>':''}<main class="container view-enter" id="main" tabindex="-1">${state.error?`<div class="notice error">${icon('info')}<div><strong>The calculation service needs attention.</strong><br>${e(state.error)}<br><button class="text-link" data-action="retry">Try again</button></div></div>`:''}${!valid?`<div class="notice error">${icon('info')}<div><strong>Valuation paused.</strong><br>${(r.errors??['Check the model inputs.']).map(e).join('<br>')}<br><button class="text-link" data-action="assumptions">Review assumptions</button></div></div>`:{company:companyView,valuation:valuationView,research:researchView}[state.view]()}<footer class="footer"><span>Source-backed. Assumption-aware.<br>Educational research · ${dated(dataset.asOf)} snapshot · INR crore unless stated</span><div class="footer-actions"><button data-action="method">Methodology</button><button data-action="checks">Data checks</button><a href="/downloads/artha-equity-project.zip" download>Source project</a></div></footer></main></div>${printReport()}`;bind();}
function dialog(title,body,buttons='',wide=false){modalReturn=document.activeElement;$('#dialog-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-header"><h2>${title}</h2><button class="icon-button" data-close-dialog aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${buttons?`<div class="modal-buttons">${buttons}</div>`:''}</section></div>`;$('.modal-backdrop').onclick=ev=>{if(ev.target===ev.currentTarget)closeDialog();};$('[data-close-dialog]').onclick=closeDialog;setTimeout(()=>$('.modal input:not([type=checkbox]),.modal textarea,.modal-body button,.modal-header button')?.focus(),0);}
function closeDialog(){const p=modalReturn;$('#dialog-root').innerHTML='';if(p?.isConnected)p.focus();}
function setDialogError(message){let el=$('#dialog-error');if(!el){el=document.createElement('div');el.id='dialog-error';el.className='form-error';$('.modal-body')?.prepend(el);}el.textContent=message;}
function download(filename,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Downloaded '+filename);}
function csv(rows){return rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');}
function exportCsv(){if(state.busy||!state.r.valid)return toast('Wait for a valid model result.');download('artha-infosys-forecast.csv',csv([['Fiscal_year','Revenue_INR_crore','EBIT_INR_crore','NOPAT_INR_crore','DA_INR_crore','Capex_INR_crore','Delta_NWC_INR_crore','FCFF_INR_crore','PV_FCFF_INR_crore'],...state.r.forecast.map(r=>[r.year,r.revenue,r.ebit,r.nopat,r.da,r.capex,r.deltaNwc,r.fcff,r.pv])]),'text/csv');event('Forecast exported',state.scenario+' case');}
function exportDialog(){if(state.busy)return toast('Wait for the model update to finish.');dialog('Take the research with you.',`<p class="modal-intro">Research packets and printed reports keep the assumptions, sources and provisional status attached.</p><button class="export-item" id="export-pdf">${icon('file')}<span><strong>Print or save as PDF</strong><small>A clean report with forecasts and evidence</small></span>${icon('arrow')}</button><button class="export-item" id="export-json">${icon('code')}<span><strong>Research packet</strong><small>JSON · facts, calculations and provenance</small></span>${icon('arrow')}</button><button class="export-item" id="export-csv">${icon('download')}<span><strong>Forecast spreadsheet</strong><small>CSV · open in Excel or Sheets</small></span>${icon('arrow')}</button><a class="export-item" href="/downloads/artha-equity-project.zip" download>${icon('code')}<span><strong>Complete source project</strong><small>Python backend, desktop UI, tests and deployment files</small></span>${icon('arrow')}</a>`);$('#export-pdf').onclick=()=>{closeDialog();event('Research report exported','Print / save as PDF');window.print();};$('#export-json').onclick=()=>download('artha-research-packet.json',JSON.stringify(makePacket(company,state.a,state.r,peers),null,2));$('#export-csv').onclick=exportCsv;}
function sourcePanel(){return `<p class="modal-intro">Official filings behind this snapshot. The report date and publication date are kept separate.</p>${company.sources.map(s=>`<article class="source-entry"><div class="source-row"><div><h3>${e(s.title)}</h3><p>Published ${dated(s.publicationDate)} · ${e(s.pages)}<br>${e(s.basis)} · ${e(s.unit)}</p></div><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">Open filing ${icon('external')}</a></div></article>`).join('')}<p class="field-hint">${company.facts.length} reviewed source facts. Snapshot fingerprints identify files; they do not certify financial accuracy.</p><button class="btn btn-outline btn-small spaced" id="download-inputs">${icon('download')}Download input snapshot</button>`;}
function checksPanel(){const checks=state.r.reconciliations??cases.base.reconciliations;return `<h3 class="checks-title">${checks.filter(x=>x.status==='pass').length} of ${checks.length} statement checks pass.</h3><p class="checks-note">Each accounting identity is independently checked. Tolerance: ₹1 crore for rounded statements.</p><div class="table-wrap"><table class="data-table compact-table"><thead><tr><th>Period</th><th>Accounting identity</th><th>Residual · Cr</th><th>Status</th></tr></thead><tbody>${checks.map(c=>`<tr><td>FY${c.year}</td><td>${e(c.label)}</td><td>${n(c.residual,1)}</td><td><span class="check-pass">${e(c.status)}</span></td></tr>`).join('')}</tbody></table></div><hr class="subtle-rule"><h3 class="checks-title">Your analysis history.</h3><div id="run-history"><p class="footnote">${runtime.api?'Loading saved Python runs…':'Server history is available in the complete application.'}</p></div><details class="disclosure"><summary>Local scenario activity</summary><div class="details-body">${state.audit.length?state.audit.slice(0,15).map(x=>`<div class="source-entry"><h3>${e(x.action)}</h3><p>${e(x.detail)} · ${new Date(x.time).toLocaleString('en-GB')}</p></div>`).join(''):'<p class="footnote">Your scenario edits and exports will appear here.</p>'}</div></details>`;}
function methodPanel(){return `<div class="methodology"><h3>Facts first. Assumptions second.</h3><p>Reported financials come from official filings. Forecast growth, margins, WACC and excess cash are explicit analyst assumptions. They are not company guidance.</p><h3>Free cash flow, discounted.</h3><p>FCFF = EBIT × (1 − operating tax) + depreciation − capex − the increase in operating working capital. Python discounts each cash flow using its date, then rebuilds terminal-year reinvestment before estimating terminal value.</p><h3>From operations to equity.</h3><p>Add assessed excess cash and subtract debt, leases and minority interests. Divide by the appropriate share count. The reported March 2026 net shares already exclude treasury shares; treasury is never deducted twice.</p><h3>Why the result is provisional.</h3><p>This is a retrospective study using reports published after the effective financial date. Employee-award period-end dilution and the excess-cash allowance still require review. Simplified working capital, lease treatment and terminal economics also need an analyst’s judgment.</p><h3>Research has a defined boundary.</h3><p>Evidence mode retrieves reviewed structured facts. A configured server-side LLM can explain those facts and model outputs. It does not replace financial calculations. Full PDF/vector RAG and FinBERT inference are separate future modules.</p><h3>A source-backed snapshot.</h3><p>Financials cover FY24–FY26. The effective model date is ${dated(state.a.valuationDate)}; the information cutoff is ${dated(state.a.informationCutoff)}. Direct BSE prices are not fabricated. Unavailable figures remain unavailable.</p></div>`;}
function evidenceDialog(tab='sources'){dialog('A trail you can follow.',`<div class="sheet-tabs" role="group" aria-label="Evidence section">${[['sources','Sources'],['checks','Checks & history'],['method','Methodology']].map(([key,label])=>`<button class="sheet-tab ${key===tab?'active':''}" data-evidence="${key}">${label}</button>`).join('')}</div>${{sources:sourcePanel,checks:checksPanel,method:methodPanel}[tab]()}`,'',true);$('.modal').querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>evidenceDialog(b.dataset.evidence));$('#download-inputs')?.addEventListener('click',()=>download('artha-source-snapshot.json',JSON.stringify({company,peers,inputManifest:company.inputManifest},null,2)));if(tab==='checks'&&runtime.api)api('/api/runs?companyId='+company.id).then(data=>{const target=$('#run-history');if(!target)return;target.innerHTML=data.runs?.length?data.runs.slice(0,8).map(r=>`<div class="source-entry"><h3>Valuation snapshot · ${new Date(r.created_at).toLocaleString('en-GB')}</h3><p>Immutable local record · ${e(r.id.slice(0,8))}</p></div>`).join(''):'<p class="footnote">No saved server runs yet.</p>';}).catch(()=>{if($('#run-history'))$('#run-history').textContent='History is temporarily unavailable.';});}
function reviewDialog(){dialog('What still needs a judgment.',`<p class="modal-intro">These limitations remain attached to every valuation and report.</p><ul class="review-list">${(state.r.warnings??[]).map(w=>`<li>${e(w)}</li>`).join('')}</ul>`);}
function numberField(label,name,value,suffix='%',extra=''){return `<div class="form-field"><label for="field-${name}">${label}${suffix?' · '+suffix:''}</label><input id="field-${name}" name="${name}" type="number" step="any" value="${value??''}" ${extra}></div>`;}
function assumptionsDialog(){const a=state.a;dialog('A few inputs. A different outcome.',`<p class="modal-intro">These are your scenario assumptions. Historical reported facts stay unchanged.</p>${!runtime.api?'<div class="form-error">Custom assumptions run in the complete Python application. This preview includes three Python-compiled cases.</div>':''}<form id="assumptions-form"><div class="form-grid"><h3 class="form-title">Revenue growth</h3><div class="growth-grid">${a.growth.map((g,i)=>numberField(`FY${2027+i}E`,'growth'+i,n(g*100,2).replaceAll(',',''),'%',runtime.api?'required min="-99.9"':'disabled')).join('')}</div><h3 class="form-title">The business</h3>${numberField('Operating margin','margin',a.margin*100,'%',runtime.api?'required min="-100" max="100"':'disabled')}${numberField('Operating tax','tax',a.tax*100,'%',runtime.api?'required min="0" max="100"':'disabled')}${numberField('Depreciation / revenue','daRatio',a.daRatio*100,'%',runtime.api?'required min="0"':'disabled')}${numberField('Capex / revenue','capexRatio',a.capexRatio*100,'%',runtime.api?'required min="0"':'disabled')}${numberField('Working capital / revenue','nwcRatio',a.nwcRatio*100,'%',runtime.api?'required':'disabled')}<div class="form-field"><label>Working-capital definition</label><input value="Receivables − payables" readonly></div><h3 class="form-title">Discounting & terminal value</h3>${numberField('WACC','wacc',a.wacc*100,'%',runtime.api?'required min="0.01" max="99.9"':'disabled')}${numberField('Perpetual growth','terminalGrowth',a.terminalGrowth*100,'%',runtime.api?'required min="-99"':'disabled')}<div class="form-field full"><button type="button" class="text-link" id="open-capm">Build WACC from CAPM →</button></div><h3 class="form-title">The equity bridge</h3>${[['Excess cash','excessCash'],['Debt','debt'],['Lease liabilities','leases'],['Non-controlling interests','nci']].map(([label,key])=>numberField(label,key,a[key],'INR crore',runtime.api?'required min="0"':'disabled')).join('')}</div><p class="field-hint">Cash is not automatically excess cash. Review restricted balances, operating reserves, lease consistency and period-end dilution. Effective date: ${dated(a.valuationDate)}.</p></form>`,`<span class="note">Calculated in Python.</span><button class="btn btn-outline" id="reset-inputs">Reset to base</button><button class="btn" type="submit" form="assumptions-form" ${runtime.api?'':'disabled'}>Update valuation</button>`,true);$('#open-capm').onclick=capmDialog;$('#reset-inputs').onclick=()=>{closeDialog();chooseCase('base');toast('Base assumptions restored.');};$('#assumptions-form').onsubmit=async ev=>{ev.preventDefault();const form=new FormData(ev.target),draft=clone(state.a);for(const key of ['margin','tax','daRatio','capexRatio','nwcRatio','wacc','terminalGrowth'])draft[key]=Number(form.get(key))/100;draft.growth=Array.from({length:5},(_,i)=>Number(form.get('growth'+i))/100);for(const key of ['excessCash','debt','leases','nci'])draft[key]=Number(form.get(key));if(draft.wacc<=draft.terminalGrowth)return setDialogError('Terminal growth must be below WACC.');state.a=draft;state.scenario='custom';event('Assumptions updated','Custom operating and discount-rate assumptions.');closeDialog();await refresh();};}
function capmDialog(){dialog('Build a cost of capital.',`<p class="modal-intro">Enter dated, sourced market inputs. CAPM estimates the cost of equity; WACC weights equity and after-tax debt costs.</p><form id="capm-form"><div class="form-grid">${numberField('Risk-free rate','risk_free_rate','','%','required min="0" max="99" placeholder="e.g. 6.5"')}${numberField('Equity beta','beta','','','required placeholder="e.g. 1.1"')}${numberField('Equity risk premium','equity_risk_premium','','%','required min="0" max="99"')}${numberField('Country premium, if separate','country_risk_premium',0,'%','required min="0" max="99"')}${numberField('Pre-tax cost of debt','cost_of_debt','','%','required min="0" max="99"')}${numberField('Tax rate','tax_rate',state.a.tax*100,'%','required min="0" max="100"')}${numberField('Market equity value','market_equity_value','','INR crore','required min="0.01"')}${numberField('Market debt value','market_debt_value','','INR crore','required min="0"')}</div><p class="field-hint">Do not add a country premium twice if your equity premium already includes it. These inputs are analyst-supplied; the app has not fetched a market WACC.</p></form><div id="capm-result"></div>`,`<button class="btn btn-outline" id="back-inputs">Back</button><button class="btn" type="submit" form="capm-form" ${runtime.api?'':'disabled'}>Calculate WACC</button>`);$('#back-inputs').onclick=assumptionsDialog;$('#capm-form').onsubmit=async ev=>{ev.preventDefault();try{const fd=new FormData(ev.target),inputs={};for(const key of ['risk_free_rate','equity_risk_premium','country_risk_premium','cost_of_debt','tax_rate'])inputs[key]=Number(fd.get(key))/100;for(const key of ['beta','market_equity_value','market_debt_value'])inputs[key]=Number(fd.get(key));const r=await api('/api/capital-cost',{inputs});if(r.valid===false)throw new Error(r.errors.join(' '));$('#capm-result').innerHTML=`<div class="capm-result"><div><span>Cost of equity</span><strong>${percent(r.cost_of_equity,2)}</strong></div><div><span>WACC</span><strong>${percent(r.wacc,2)}</strong></div></div><button class="btn btn-outline btn-small spaced" id="apply-wacc">Use this WACC</button>`;$('#apply-wacc').onclick=async()=>{state.a.wacc=r.wacc;state.a.capitalCostInputs=inputs;state.scenario='custom';event('CAPM applied','WACC derived from user-supplied market inputs.');closeDialog();await refresh();toast('Your calculated WACC is applied.');};}catch(error){setDialogError(error.message);}};}
function saveDialog(){if(state.busy||!state.r.valid)return toast('Wait for a valid valuation.');dialog('Keep this point of view.',`<p class="modal-intro">Save the assumptions in this browser. Export a research packet for a portable copy.</p><form id="save-form"><div class="form-field"><label for="scenario-name">Scenario name</label><input id="scenario-name" maxlength="70" required value="${e('Infosys · '+state.scenario+' case')}"></div></form>`,`<button class="btn" type="submit" form="save-form">Save scenario</button>`);$('#save-form').onsubmit=async ev=>{ev.preventDefault();const name=$('#scenario-name').value.trim();if(!name)return;const id=crypto.randomUUID?.()??Date.now().toString(36)+Math.random().toString(36).slice(2);state.scenarios.unshift({id,name,companyId:company.id,assumptions:clone(state.a),value:state.r.perShare,date:new Date().toISOString(),scenario:state.scenario});state.scenarios=state.scenarios.slice(0,30);write('scenarios',state.scenarios);event('Scenario saved',name);closeDialog();if(runtime.api){await refresh(true);toast(state.error?'Saved in this browser; server save needs attention.':'Scenario and Python snapshot saved.');}else toast('Scenario saved in this browser.');};}
function savedDialog(){dialog('Your saved scenarios.',state.scenarios.length?state.scenarios.map(s=>`<div class="save-row"><div><strong>${e(s.name)}</strong><small>${money(s.value,2)} per share · ${new Date(s.date).toLocaleDateString('en-GB')}</small></div><div class="save-actions"><button class="btn btn-outline btn-small" data-load="${e(s.id)}">Open</button><button class="icon-button" aria-label="Delete ${e(s.name)}" data-delete="${e(s.id)}">${icon('trash')}</button></div></div>`).join(''):'<div class="empty">No saved scenarios yet.<br>Build a valuation, then save the assumptions you want to revisit.</div>');$('.modal').querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{const s=state.scenarios.find(x=>x.id===b.dataset.load);if(s.companyId!==company.id)return toast('That company is not in the current coverage.');if(!runtime.api&&(!s.scenario||s.scenario==='custom'))return toast('Open the complete application to restore custom assumptions.');state.a=clone(s.assumptions);state.scenario=s.scenario??'custom';closeDialog();state.view='valuation';location.hash='valuation';if(runtime.api)refresh();else{state.r=clone(cases[state.scenario]);render();}});$('.modal').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{state.scenarios=state.scenarios.filter(s=>s.id!==b.dataset.delete);write('scenarios',state.scenarios);savedDialog();});}
function searchDialog(){dialog('Find your next question.',`<label class="sr-only" for="search-input">Company or workspace section</label><input class="search-box" id="search-input" placeholder="A company, a view, a question…" autocomplete="off"><div id="search-results"></div>`);const update=()=>{const q=$('#search-input').value.toLowerCase().trim();const items=[{label:'Infosys Limited',detail:'INFY · BSE 500209',action:'company'},{label:'Cash-flow valuation',detail:'Model & assumptions',action:'valuation'},{label:'Peer comparison',detail:'TCS · HCLTech · Wipro',action:'peers'},{label:'Research',detail:'Ask the loaded evidence',action:'research'},{label:'Sources & data checks',detail:'Official financial filings',action:'evidence'},{label:'Saved scenarios',detail:state.scenarios.length+' in this browser',action:'saved'}].filter(x=>(x.label+' '+x.detail).toLowerCase().includes(q));$('#search-results').innerHTML=items.length?items.map(x=>`<button class="search-result" data-search-action="${x.action}"><span>${e(x.label)}</span><small>${e(x.detail)}</small></button>`).join(''):`<button class="search-result" data-search-action="ask"><span>Ask about “${e($('#search-input').value)}”</span><small>Research</small></button><p class="field-hint">Full valuation coverage is currently Infosys. TCS, HCLTech and Wipro are available as peers; arbitrary tickers are not presented as analyzed.</p>`;$('#search-results').querySelectorAll('[data-search-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.searchAction;if(action==='ask'){const q=$('#search-input').value;go('research');ask(q);}else{closeDialog();handle(action);}});};$('#search-input').oninput=update;update();}
function offlineTopic(question){const q=question.toLowerCase();if(/wacc|discount|terminal|cost of capital/.test(q))return 'discount';if(/cash|debt|bridge|share|treasury|dilut/.test(q))return 'bridge';if(/peer|compar|multiple/.test(q))return 'peers';if(/risk|limitation|buy|sell|invest|trust/.test(q))return 'risks';if(/source|report|data|audit/.test(q))return 'sources';if(/revenue|sales|growth|performance|profit|margin/.test(q))return 'growth';if(/value|valuation|fcff|dcf|explain/.test(q))return 'valuation';return null;}
async function ask(question){question=String(question).trim().slice(0,2000);if(!question||state.asking||state.busy)return;state.messages.push({role:'user',text:question});state.asking=true;render();try{let answer;if(runtime.api)answer=await api('/api/assistant',{companyId:company.id,question,assumptions:state.a,marketOverrides:state.market});else{const topic=offlineTopic(question);answer=topic?clone(compiled.answers[company.id][state.scenario==='custom'?'base':state.scenario][topic]):{title:'Research coverage',body:'This workspace can explain the loaded financial history, valuation, assumptions, shares, peer coverage and limitations. It does not browse or invent an answer outside those sources.',citations:[],mode:'evidence'};answer.retrieval=retrieveEvidence(question,company,peers);}if(!answer.title||!answer.body||!Array.isArray(answer.citations))throw new Error('The explanation service returned an invalid response.');state.messages.push({role:'assistant',answer});}catch(error){state.messages.push({role:'assistant',answer:{title:'The research service needs a moment.',body:error.message,citations:[],mode:'evidence'}});}finally{state.asking=false;render();$('#question')?.focus({preventScroll:true});$('#question-form')?.scrollIntoView({block:'nearest',behavior:'smooth'});}}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
function marketDialog(){if(!runtime.api)return dialog('Use reviewed market evidence.',`<p class="modal-intro">Market imports run in the complete Python application. Import a direct official BSE close and compatible shares to enable market comparisons. The preview never invents a quote.</p><a class="btn" href="/downloads/artha-equity-project.zip" download>Get the complete application</a>`);const coverage=[{...company,netSharesCrore:company.shares.netCrore},...peers];let fileEvidence=null;dialog('Add the market evidence.',`<p class="modal-intro">Choose an official BSE Bhav Copy. Its close is paired with a reviewed, same-date share observation.</p><form id="market-form"><div class="form-grid"><div class="form-field"><label for="market-company">Company</label><select id="market-company">${coverage.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select></div><div class="form-field"><label for="market-date">Trading date</label><input id="market-date" value="${state.a.valuationDate}" readonly></div><div class="form-field full upload-file"><label for="market-file">Official BSE CSV · up to 10 MB</label><input id="market-file" type="file" accept=".csv,text/csv" required><small id="market-file-status">The matching scrip and CLOSE are extracted; no quote is estimated.</small></div><div class="form-field"><label for="market-shares">Net outstanding shares · crore</label><input id="market-shares" type="number" step="any" min="0.0001" value="${company.shares.netCrore}" required></div><div class="form-field"><label for="market-share-date">Share effective date</label><input id="market-share-date" type="date" value="${state.a.valuationDate}" required></div><div class="form-field full"><label for="market-url">Official BSE source URL</label><input id="market-url" type="url" value="https://www.bseindia.com/markets/MarketInfo/BhavCopy.aspx" required></div><div class="form-field full"><label for="market-share-source">Share-count source URL</label><input id="market-share-source" type="url" value="${e(company.sources.find(s=>s.id===company.shares.sourceId)?.url??'')}" required></div><h3 class="form-title">Optional enterprise-value inputs · INR crore</h3>${[['Debt','market-debt'],['Assessed cash','market-cash'],['Leases','market-leases'],['Minority interests','market-nci'],['Book equity, owners','market-bookEquity'],['Reported EBITDA','market-ebitda']].map(([label,id])=>`<div class="form-field"><label for="${id}">${label}</label><input id="${id}" type="number" step="any" min="0" placeholder="Not reviewed"></div>`).join('')}<div class="form-field full"><label for="market-financial-source">Official-company financial source · required if optional values are supplied</label><input id="market-financial-source" type="url" placeholder="Reviewed financial statement URL"></div></div><label class="check-line"><input id="market-reviewed" type="checkbox" required>I reviewed the original BSE file, source, share count and reporting dates. A file fingerprint records identity; it does not certify origin.</label></form>`,`<button class="btn" type="submit" form="market-form">Import observation</button>`,true);
const loadFile=async()=>{fileEvidence=null;try{const file=$('#market-file').files[0];if(!file)return;if(file.size>10_000_000)throw new Error('Choose a CSV smaller than 10 MB.');if(!crypto.subtle)throw new Error('File fingerprinting requires HTTPS or localhost.');const date=state.a.valuationDate,tokens=[date.replaceAll('-',''),date.slice(8,10)+date.slice(5,7)+date.slice(2,4)];if(!tokens.some(t=>file.name.includes(t)))throw new Error('The filename must contain the selected trading date.');const rows=parseCsv(await file.text());const headers=rows.shift().map(x=>x.trim().toUpperCase().replace(/^\uFEFF/,''));const code=['SC_CODE','SCRIPCODE','SCRIP_CODE','FININSTRMID'].map(x=>headers.indexOf(x)).find(i=>i>=0),close=['CLOSE','CLOSE_PRICE','CLOSEPRICE','CLSPRIC'].map(x=>headers.indexOf(x)).find(i=>i>=0);if(code===undefined||close===undefined)throw new Error('The CSV needs recognized BSE scrip and closing-price columns.');const c=coverage.find(c=>c.id===$('#market-company').value),matching=rows.filter(r=>String(r[code]).trim().replace(/\.0$/,'').padStart(6,'0')===c.scrip);if(matching.length!==1)throw new Error('The file must contain exactly one row for BSE '+c.scrip+'.');const price=Number(matching[0][close]);if(!Number.isFinite(price)||price<=0)throw new Error('The matching close must be positive.');const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer()),hash=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('');fileEvidence={price,sourceArtifact:file.name,sourceFileSha256:hash};$('#market-file-status').textContent='Matched '+c.scrip+' · direct close '+money(price,2)+' · SHA-256 recorded.';}catch(error){setDialogError(error.message);}};$('#market-file').onchange=loadFile;$('#market-company').onchange=()=>{const c=coverage.find(c=>c.id===$('#market-company').value);$('#market-shares').value=c.id===company.id?company.shares.netCrore:'';$('#market-share-source').value=c.id===company.id?(company.sources.find(s=>s.id===company.shares.sourceId)?.url??''):'';loadFile();};$('#market-form').onsubmit=async ev=>{ev.preventDefault();try{if(!fileEvidence)throw new Error('Choose and validate the original BSE CSV.');const id=$('#market-company').value,date=state.a.valuationDate,shareDate=$('#market-share-date').value,shares=Number($('#market-shares').value),sourceUrl=$('#market-url').value,shareSourceUrl=$('#market-share-source').value,host=new URL(sourceUrl).hostname;if(new URL(sourceUrl).protocol!=='https:'||(host!=='bseindia.com'&&!host.endsWith('.bseindia.com')))throw new Error('Use an HTTPS bseindia.com market source.');if(new URL(shareSourceUrl).protocol!=='https:')throw new Error('Use an HTTPS share-count source.');if(shareDate!==date)throw new Error('The share date must match '+date+'.');if(id===company.id&&Math.abs(shares-company.shares.netCrore)>1e-6)throw new Error('The count differs from the reviewed company snapshot. Update the source data first.');const numeric=key=>$('#market-'+key).value===''?null:Number($('#market-'+key).value);if(['debt','cash','leases','nci','bookEquity','ebitda'].some(k=>numeric(k)!==null)&&!$('#market-financial-source').value)throw new Error('Add the official-company financial source for optional values.');state.market[id]={market:{...fileEvidence,date,method:'direct_bse_close',reviewed:true,sourceUrl},shareDate,netSharesCrore:shares,shareSourceUrl,debt:numeric('debt'),cash:numeric('cash'),leases:numeric('leases'),nci:numeric('nci'),bookEquity:numeric('bookEquity'),ebitda:numeric('ebitda'),financialSourceUrl:$('#market-financial-source').value};write('market',state.market);event('Market evidence imported',id+' · '+date);closeDialog();await refresh();toast('Reviewed market observation imported.');}catch(error){setDialogError(error.message);}};}
function handle(action){const handlers={company:()=>go('company'),valuation:()=>go('valuation'),research:()=>go('research'),peers:()=>{state.subview='peers';go('valuation');},export:exportDialog,csv:exportCsv,evidence:()=>evidenceDialog(),checks:()=>evidenceDialog('checks'),method:()=>evidenceDialog('method'),review:reviewDialog,assumptions:assumptionsDialog,save:saveDialog,saved:savedDialog,search:searchDialog,market:marketDialog,retry:()=>refresh(),'forecast-detail':()=>{state.fullForecast=!state.fullForecast;render();},'new-chat':()=>{state.messages=[];render();}};handlers[action]?.();}
function bind(){document.querySelectorAll('.nav-link,.wordmark').forEach(a=>a.onclick=ev=>{ev.preventDefault();go(a.hash.slice(1));});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action));document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>chooseCase(b.dataset.case));document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{state.chart=b.dataset.chart;render();});document.querySelectorAll('[data-statement]').forEach(b=>b.onclick=()=>{state.statement=b.dataset.statement;state.statementsOpen=true;render();});document.querySelectorAll('[data-remember]').forEach(d=>d.ontoggle=()=>{state[d.dataset.remember]=d.open;});document.querySelectorAll('[data-subview]').forEach(b=>b.onclick=()=>{state.subview=b.dataset.subview;render();});document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));$('#question-form')?.addEventListener('submit',ev=>{ev.preventDefault();ask($('#question').value);});$('#question')?.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&!ev.shiftKey){ev.preventDefault();ask(ev.target.value);}});}
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['company','valuation','research'].includes(view)&&view!==state.view){state.view=view;render();}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeDialog();if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){ev.preventDefault();searchDialog();}if(ev.key==='Tab'&&$('.modal')){const controls=[...$('.modal').querySelectorAll('button,a[href],input,textarea,select')].filter(x=>!x.disabled),first=controls[0],last=controls.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
render();
if(runtime.api){refresh();api('/api/health').then(data=>{state.assistantMode=data.assistantMode;}).catch(()=>{});}
